\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{fig_overview_pb}
\caption{Overview of three findings. \textbf{(a)}~Action-collapsed policies inflate CAR: 91.5\% reported safety drops to ${\approx}$\,0\% after displacement filtering (dfCAR). \textbf{(b)}~EE-only SDF refinement is counterproductive: the SDF gradient pushes the end-effector away but joint coupling rotates unmonitored links into obstacles, reducing CAR below unrefined baselines. \textbf{(c)}~Collision-free demonstrations account for ${\sim}$26\,pp CAR gain ($p < 0.001$); SDF supervision adds only 2.3\,pp ($p = 0.131$, n.s.).}
\label{fig:overview}
\end{figure*}

